          "plainKo": "인공지능이 똑똑하게 답하려면 회사가 가진 자료를 잘 찾아서 넣어줘야 합니다. 그 '찾아주고 담아주는' 소프트웨어 회사들의 매출이 다시 빨라지고 있습니다.",
